var tocUrls = [];
var totalText = String(org.jsoup.Jsoup.parse(result).select('.book_list2').prev('h2').text());
var totalMatch = totalText.match(/共\s*(\d+)\s*章/);
if(totalMatch) {
    var totalChapters = parseInt(totalMatch[1]);
    var totalPages = Math.ceil(totalChapters / 100);
    for(var i = 1; i <= totalPages; i++) {
        tocUrls.push(baseUrl + 'index_' + i + '.html');
    }
}
tocUrls;

