function FQ_checkLoginState(jv) {
  var msg = '';
  try {
    var s = '';
    try {
      s = String(jv.ajax('https://wap.39shuwu.com/user/userinfo.html') || '');
    } catch (e1) {
      try {
        s = String(jv.get('https://wap.39shuwu.com/user/userinfo.html', {}) || '');
      } catch (e2) {
        s = '';
      }
    }
    if (!s) {
      msg = '检查失败: 无响应';
    } else if (s.indexOf('退出登录') >= 0 || s.indexOf('修改密码') >= 0) {
      msg = '已登录';
    } else if (s.indexOf('趣书吧会员登录') >= 0 || s.indexOf('请登录') >= 0) {
      msg = '未登录';
    } else {
      msg = '状态未知(未登录或页面结构变更)';
    }
  } catch (e) {
    msg = '检查失败:' + e;
  }
  try { jv.put('fqLoginMsg', msg); } catch (e3) {}
  try { jv.upLoginData({ '登录状态': msg }); } catch (e4) {}
  try { jv.toast(msg); } catch (e5) {}
  try { jv.longToast(msg); } catch (e6) {}
  try { jv.reLoginView(false); } catch (e7) {}
}
function FQ_openLoginPage(jv) {
  try {
    jv.showBrowser('https://wap.39shuwu.com/user/login.html');
  } catch (e) {
    try { jv.toast('打开登录页失败:' + e); } catch (e2) {}
  }
}

